?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title><?=e($title)?> | Gonzaga's Apparel</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin.css"></head><body class="admin-page"><header class="admin-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><div><a href="dashboard.php">DASHBOARD</a></div></header><main class="admin-shell narrow"><div class="section-kicker">PRODUCT MANAGEMENT <span></span></div><h1><?=e($title)?></h1><?php if(!empty($errors)):?><div class="alert error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form class="admin-form" action="<?=e($action)?>" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if($id):?><input type="hidden" name="id" value="<?=$id?>"><?php endif;?><label>NAME<input name="name" type="text" maxlength="150" value="<?=e($product['name']??'')?>" required></label><label>CATEGORY<select name="category_id" required><option value="">Select category</option><?php foreach($categories as $category):?><option value="<?=intval($category['id'])?>" <?=intval($product['category_id']??0)===intval($category['id'])?'selected':''?>><?=e($category['name'])?></option><?php endforeach;?></select></label><label>DESCRIPTION<textarea name="description" rows="5" maxlength="2000"><?=e($product['description']??'')?></textarea></label><div class="form-grid"><label>PRICE<input name="price" type="number" min="0" step="0.01" value="<?=e((string)($product['price']??'0.00'))?>" required></label><label>STOCK<input name="stock" type="number" min="0" step="1" value="<?=e((string)($product['stock']??'0'))?>" required></label></div><label>IMAGE PATH<input name="image" type="text" value="<?=e($product['image']??'black-tshirt-placeholder.svg') ?>" placeholder="example.svg"></label><?php if($id):?><label class="check"><input name="is_active" type="checkbox" value="1" <?=!empty($product['is_active'])?'checked':''?>> Active product</label><?php endif;?><button class="button button--filled" type="submit">SAVE PRODUCT</button></form></main></body></html>
